from pathlib import Path

ROOT = Path('/opt/tg-job-agent')


def replace_once(path, old, new):
    p = ROOT / path
    text = p.read_text()
    if old not in text:
        raise SystemExit(f'PATCH_ANCHOR_MISSING {path}: {old[:80]!r}')
    p.write_text(text.replace(old, new, 1))
    print('PATCHED', path)


